{
  "id": "sales-report-message",
  "name": "Sales report message",
  "description": "Renders app.sales.report CUSTOM events as an inline monthly sales table inside the conversation.",
  "version": "0.0.1",
  "capabilities": [
    "headless"
  ],
  "data": {
    "messageUI": true,
    "events": [
      "app.sales.report"
    ]
  },
  "authoring": {
    "intents": [
      "show a monthly sales report table in the conversation",
      "在聊天消息里显示月度销售报表表格"
    ],
    "visualRole": "inline sales report data message inside the conversation"
  }
}

import { z } from "zod";

export const SALES_REPORT_EVENT = "app.sales.report";

const salesReportRowSchema = z
  .object({
    month: z.string().min(1),
    revenue: z.coerce.number(),
    order_count: z.coerce.number().optional(),
    orderCount: z.coerce.number().optional(),
  })
  .transform((row) => ({
    month: row.month,
    revenue: row.revenue,
    orderCount: row.order_count ?? row.orderCount ?? 0,
  }));

const salesReportPayloadSchema = z
  .object({
    title: z.string().optional(),
    rows: z.array(salesReportRowSchema).default([]),
  })
  .transform((report) => ({
    title: report.title && report.title.trim().length > 0 ? report.title.trim() : undefined,
    rows: report.rows,
  }));

export type SalesReport = z.output<typeof salesReportPayloadSchema>;

/**
 * Event schema registered through `Agent.appEventSchemas` for the
 * `app.sales.report` CUSTOM event. The envelope stays intact so the message
 * component can read `value.format` and the JSON string in `value.payload`.
 */
export const salesReportEventSchema = z.object({
  format: z.string().optional(),
  payload: z
    .union([z.string(), z.record(z.string(), z.unknown()), z.array(z.unknown())])
    .optional(),
});

function safeJsonParse(text: string): unknown {
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return undefined;
  }
}

export type SalesReportReadResult =
  | { status: "ok"; report: SalesReport }
  | { status: "invalid" }
  | { status: "unsupported" };

/**
 * Reads the report out of the data message payload: either the CUSTOM event
 * value (`{ format, payload }`) or an already decoded report object.
 */
export function readSalesReportState(data: unknown): SalesReportReadResult {
  const envelope = typeof data === "string" ? safeJsonParse(data) : data;

  if (!envelope || typeof envelope !== "object" || Array.isArray(envelope)) {
    return { status: "invalid" };
  }

  const record = envelope as Record<string, unknown>;
  const format = typeof record.format === "string" ? record.format.trim().toLowerCase() : undefined;

  if (format && format !== "json") {
    return { status: "unsupported" };
  }

  const payload = "payload" in record ? record.payload : record;

  if (payload === undefined || payload === null) {
    return { status: "invalid" };
  }

  const decoded = typeof payload === "string" ? safeJsonParse(payload) : payload;

  if (decoded === undefined) {
    return { status: "invalid" };
  }

  const parsed = salesReportPayloadSchema.safeParse(decoded);

  return parsed.success ? { status: "ok", report: parsed.data } : { status: "invalid" };
}

import { Fragment, useMemo, useState } from "react";
import {
  defineDataMessageUI,
  useAgentUILocaleCode,
} from "@za38.03/agent-ui-plugins";
import { getProjectMessages } from "../../application/i18n/messages";
import { SALES_REPORT_EVENT, readSalesReportState } from "./schema";
import "./styles.css";

export function SalesReportMessage({ data }: { data: unknown }) {
  const localeCode = useAgentUILocaleCode();
  const labels = getProjectMessages(localeCode).salesReport;
  const state = readSalesReportState(data);
  const [descending, setDescending] = useState(true);
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  const rows = useMemo(() => {
    if (state.status !== "ok") {
      return [];
    }

    return [...state.report.rows].sort((left, right) =>
      descending ? right.revenue - left.revenue : left.revenue - right.revenue,
    );
  }, [state, descending]);

  if (state.status === "unsupported") {
    return (
      <p className="sales-report-message sales-report-message--notice" role="status">
        {labels.unsupportedFormat}
      </p>
    );
  }

  if (state.status === "invalid") {
    return (
      <p className="sales-report-message sales-report-message--notice" role="alert">
        {labels.invalid}
      </p>
    );
  }

  const title = state.report.title ?? labels.fallbackTitle;
  const numberFormat = new Intl.NumberFormat(localeCode);
  const sortLabel = descending ? labels.sortRevenueAscending : labels.sortRevenueDescending;
  const toggleMonth = (month: string) => {
    setExpandedMonth((current) => (current === month ? null : month));
  };

  return (
    <section className="sales-report-message" aria-label={title}>
      <h3 className="sales-report-message__title">{title}</h3>
      {rows.length === 0 ? (
        <p className="sales-report-message__empty">{labels.emptyRows}</p>
      ) : (
        <table className="sales-report-message__table" aria-label={title}>
          <thead>
            <tr>
              <th scope="col">{labels.month}</th>
              <th scope="col" aria-sort={descending ? "descending" : "ascending"}>
                <button
                  type="button"
                  className="sales-report-message__sort"
                  onClick={() => setDescending((current) => !current)}
                  aria-label={sortLabel}
                  title={sortLabel}
                >
                  {labels.revenue}
                  <span aria-hidden="true">{descending ? "\u2193" : "\u2191"}</span>
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, index) => {
              const expanded = expandedMonth === row.month;

              return (
                <Fragment key={`${row.month}-${index}`}>
                  <tr
                    className="sales-report-message__row"
                    tabIndex={0}
                    aria-expanded={expanded}
                    data-expanded={expanded ? "true" : undefined}
                    onClick={() => toggleMonth(row.month)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault();
                        toggleMonth(row.month);
                      }
                    }}
                  >
                    <th scope="row">{row.month}</th>
                    <td className="sales-report-message__revenue">
                      {numberFormat.format(row.revenue)}
                    </td>
                  </tr>
                  {expanded ? (
                    <tr className="sales-report-message__detail">
                      <td colSpan={2}>
                        <span className="sales-report-message__detail-label">
                          {labels.orderCount}
                        </span>
                        <strong className="sales-report-message__detail-value">
                          {numberFormat.format(row.orderCount)}
                        </strong>
                      </td>
                    </tr>
                  ) : null}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      )}
    </section>
  );
}

export const salesReportMessageUI = defineDataMessageUI<unknown>({
  name: SALES_REPORT_EVENT,
  render: SalesReportMessage,
});

.sales-report-message {
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
  margin: 0;
  color: inherit;
  font-size: 13px;
  line-height: 1.5;
}

.sales-report-message__title {
  margin: 0 0 8px;
  font-size: 14px;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.sales-report-message__table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.sales-report-message__table th,
.sales-report-message__table td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--border, rgba(127, 127, 127, 0.25));
  text-align: left;
  font-weight: 400;
}

.sales-report-message__table thead th {
  color: var(--muted, #6b7280);
  font-size: 12px;
}

.sales-report-message__table thead th:nth-child(2),
.sales-report-message__revenue {
  text-align: right;
}

.sales-report-message__sort {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.sales-report-message__sort:hover,
.sales-report-message__sort:focus-visible {
  color: var(--foreground, currentColor);
  text-decoration: underline;
}

.sales-report-message__row {
  cursor: pointer;
}

.sales-report-message__row:hover,
.sales-report-message__row:focus-visible {
  background: var(--accent, rgba(127, 127, 127, 0.08));
}

.sales-report-message__row:focus-visible {
  outline: 2px solid var(--ring, rgba(59, 130, 246, 0.6));
  outline-offset: -2px;
}

.sales-report-message__row[data-expanded="true"] th {
  font-weight: 600;
}

.sales-report-message__detail td {
  color: var(--muted, #6b7280);
  background: var(--accent, rgba(127, 127, 127, 0.06));
}

.sales-report-message__detail-label {
  margin-right: 6px;
}

.sales-report-message__detail-value {
  color: var(--foreground, inherit);
  font-weight: 600;
}

.sales-report-message__empty,
.sales-report-message--notice {
  margin: 0;
  color: var(--muted, #6b7280);
}

import type { UIPluginDefinition, UIPluginManifest } from "@za38.03/agent-ui-plugins";
import manifestJson from "./manifest.json";
import { salesReportMessageUI } from "./index";

const definition: UIPluginDefinition = {
  manifest: manifestJson as UIPluginManifest,
  dataMessageUIs: [salesReportMessageUI],
  Component: () => null,
};

export default definition;

/**
 * Project-owned UI copy shared by application Plugin code.
 * Every entry keeps en-US / zh-CN parity.
 */
const zhCN = {
  salesReport: {
    fallbackTitle: "月度销售",
    month: "月份",
    revenue: "收入",
    orderCount: "订单数量",
    emptyRows: "报表中没有可展示的月度数据。",
    invalid: "报表数据格式不正确。",
    unsupportedFormat: "暂不支持该报表格式。",
    sortRevenueAscending: "按收入从低到高排序",
    sortRevenueDescending: "按收入从高到低排序",
  },
};

export type ProjectMessages = typeof zhCN;

const enUS: ProjectMessages = {
  salesReport: {
    fallbackTitle: "Monthly sales",
    month: "Month",
    revenue: "Revenue",
    orderCount: "Orders",
    emptyRows: "This report has no monthly rows to display.",
    invalid: "Invalid sales report data.",
    unsupportedFormat: "Unsupported report format.",
    sortRevenueAscending: "Sort by revenue ascending",
    sortRevenueDescending: "Sort by revenue descending",
  },
};

const projectMessages: Record<string, ProjectMessages> = {
  "zh-CN": zhCN,
  "en-US": enUS,
};

export function getProjectMessages(locale: string): ProjectMessages {
  return projectMessages[locale] ?? zhCN;
}

